56	/**
57	 * Gestione asset di un singolo record (digital-hub #16).
58	 *
59	 * Page record-scoped, full-width, fuori dalla navigazione: si raggiunge solo
60	 * dall'azione {@see \AtrioTeam\DigitalHub\Assets\Filament\Actions\ManageAssetsAction}
61	 * nella tabella di una resource. La route porta owner via coppia polimorfica
62	 * (morph alias + chiave): `/assets/{ownerType}/{owner}`, così la pagina è
63	 * generica per qualunque modello che usa il trait HasAssets, non solo Product.
64	 *
65	 * Lo stato dell'UI (folder attiva, ecc.) sarà aggiunto negli step successivi
66	 * di #16a; qui c'è solo lo scheletro navigabile.
67	 */
68	class AssetManager extends Page implements HasActions
69	{
70	    use InteractsWithActions;
71	
72	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedFolderOpen;
73	
74	    protected static ?string $slug = 'assets';
75	
76	    protected string $view = 'digital-hub::filament.pages.asset-manager';
77	
78	    protected Width|string|null $maxContentWidth = Width::Full;
79	
80	    /**
81	     * Layout "base" (solo body, niente sidebar/topbar): la pagina è un editor di
82	     * asset a tutto schermo, presentato come un "finto modal" che si chiude con la
83	     * X tornando al catalogo (vedi blade). Il layout base include comunque gli
84	     * stili/script Filament e il componente notifiche, quindi toast e modali delle
85	     * action continuano a funzionare.
86	     */
87	    protected static string $layout = 'filament-panels::components.layout.base';
88	
89	    /** icona di "sposta", usata per file e cartelle */
90	    protected Heroicon $moveActionIcon = Heroicon::OutlinedArrowUpOnSquareStack;
91	
92	    /** Morph alias del record proprietario (es. `product`). */
93	    public string $ownerType;
94	
95	    /** Chiave primaria del record proprietario. */
96	    public int|string $ownerKey;
97	
98	    /** Folder attualmente selezionata; null = root (tutti gli asset del record). */
99	    public ?int $activeFolderId = null;
100	
101	    /**
102	     * URL della lista da cui si è arrivati (catturato dal Referer alla mount),
103	     * per il link "indietro". null se assente o non locale. È public così
104	     * sopravvive alle update Livewire successive (la mount gira una sola volta).
105	     */
106	    public ?string $returnUrl = null;
107	
108	    /**
109	     * Id dei media selezionati per le azioni multiple (checkbox sulle card).
110	     * @var array<int, int|string>
111	     */
112	    public array $selectedAssetIds = [];
113	
114	    /** URL dell'ultimo share creato, mostrato nel modal "share-link" (22g). */
115	    public ?string $lastShareUrl = null;
116	
117	    /**
118	     * Cache per-request del record risolto (privata: non serializzata da Livewire).
119	     * @var (Model&OwnsAssets)|null
120	     */
121	    private ?Model $ownerModel = null;
122	
123	    /**
124	     * Cache per-request delle folder del record (privata: non serializzata da Livewire).
125	     * @var null|EloquentCollection<int,AssetFolder>
126	     */
127	    private ?EloquentCollection $folderCache = null;
128	
129	    /**
130	     * Cache per-request dei media contenuti nei sottoalberi delle sottocartelle
131	     * visibili, condivisa tra preview delle tile cartella e check del polling.
132	     * @var null|\Illuminate\Support\Collection<int, Media>
133	     */
134	    private ?\Illuminate\Support\Collection $subfolderMediaCache = null;
135	
136	    #[Override]
137	    public static function getRoutePath(Panel $panel): string
138	    {
139	        return '/assets/{ownerType}/{owner}';
140	    }
141	
142	    public static function shouldRegisterNavigation(): bool
143	    {
144	        return false;
145	    }
146	
147	    /**
148	     * I parametri di route (ownerType, owner) sono iniettati da Livewire.
149	     */
150	    public function mount(string $ownerType, int|string $owner): void
151	    {
152	        $this->ownerType = $ownerType;
153	        $this->ownerKey = $owner;
154	
155	        // valida subito: record risolvibile e dotato del trait HasAssets
156	        $this->resolveOwner();
157	
158	        // la lista di provenienza (con i suoi filtri, es. sottocategoria) è
159	        // esattamente la pagina che ha linkato qui: la prendiamo dal Referer.
160	        // Fallback (link diretto/tab nuova, niente referer): la lista della
161	        // resource del record, senza filtri.
162	        $this->returnUrl = $this->resolveReturnUrl(request()->headers->get('referer'))
163	            ?? $this->resourceIndexUrl();
164	    }
165	
166	    /**
167	     * Valida l'URL di ritorno: accetta solo URL dello stesso host dell'app (no
168	     * open redirect verso domini esterni) e scarta l'auto-riferimento alla
169	     * pagina asset stessa (es. reload). null se non valido.
170	     */
171	    private function resolveReturnUrl(?string $url): ?string
172	    {
173	        if (! is_string($url) || $url === '') {
174	            return null;
175	        }
176	
177	        $host = parse_url($url, PHP_URL_HOST);
178	        if ($host !== null && $host !== request()->getHost()) {
179	            return null;
180	        }
181	
182	        // non puntare a sé stessa (la pagina asset): eviterebbe un "indietro" che non torna indietro
183	        if (str_contains((string) parse_url($url, PHP_URL_PATH), '/assets/')) {
184	            return null;
185	        }
186	
187	        return $url;
188	    }
189	
190	    /**
191	     * URL della lista (index) della resource Filament del record, da usare come
192	     * fallback quando manca un Referer valido. null se il record non ha una
193	     * resource registrata nel pannello o l'URL non è risolvibile.
194	     */
195	    private function resourceIndexUrl(): ?string
196	    {
197	        /** @var class-string<\Filament\Resources\Resource>|null $resource */
198	        $resource = \Filament\Facades\Filament::getModelResource($this->resolveOwner());
199	        if ($resource === null) {
200	            return null;
201	        }
202	
203	        try {
204	            $url = $resource::getUrl('index');
205	
206	            return $url ?: null;
207	        } catch (\Throwable) {
208	            return null;
209	        }
210	    }
211	
212	    /**
213	     * Risolve il record proprietario dalla coppia (morph alias, chiave).
214	     * 404 se il tipo non è mappato, il record non esiste o non è OwnsAssets.
215	     *
216	     * @return Model&OwnsAssets
217	     */
218	    public function resolveOwner(): Model
219	    {
220	        if ($this->ownerModel !== null) {
221	            return $this->ownerModel;
222	        }
223	
224	        $class = Relation::getMorphedModel($this->ownerType) ?? $this->ownerType;
225	        abort_unless(class_exists($class), 404);
226	
227	        /** @var class-string<Model> $class */
228	        $record = $class::query()->find($this->ownerKey);
229	        abort_unless($record instanceof OwnsAssets, 404);
230	
231	        return $this->ownerModel = $record;
232	    }
233	
234	    #[Override]
235	    public function getTitle(): string|Htmlable
236	    {
237	        $owner = $this->resolveOwner();
238	        $name = $owner->getAttribute('name');
239	        $key = $owner->getKey();
240	        $label = is_string($name) && $name !== ''
241	            ? $name
242	            : '#' . (is_scalar($key) ? (string) $key : '');
243	
244	        return (string) __('digital-hub::assets.title_for', ['owner' => $label]);
245	    }
246	
247	    /**
248	     * Nessun heading di pagina Filament: il titolo è renderizzato dalla barra del
249	     * finto modal nel blade. Tornando '' (vuoto) il componente di pagina non
250	     * disegna affatto l'header, evitando il doppione.
251	     */
252	    #[Override]
253	    public function getHeading(): string|Htmlable
254	    {
255	        return '';
256	    }
257	
258	    /**
259	     * Tutte le folder del record, caricate una sola volta per request.
260	     *
261	     * @return EloquentCollection<int, AssetFolder>
262	     */
263	    public function allFolders(): EloquentCollection
264	    {
265	        if ($this->folderCache !== null) {
266	            return $this->folderCache;
267	        }
268	
269	        return $this->folderCache = $this->resolveOwner()->allAssetFolders();
270	    }
271	
272	    /**
273	     * Seleziona la folder attiva (null = root). Ignora id non appartenenti al
274	     * record (es. manomissione del payload Livewire).
275	     */
276	    public function selectFolder(?int $folderId): void
277	    {
278	        // cambiando vista la selezione corrente non ha più senso
279	        $this->selectedAssetIds = [];
280	
281	        if ($folderId === null) {
282	            $this->activeFolderId = null;
283	
284	            return;
285	        }
286	
287	        if ($this->allFolders()->firstWhere('id', $folderId) !== null) {
288	            $this->activeFolderId = $folderId;
289	        }
290	    }
291	
292	    /**
293	     * Svuota la selezione corrente (pulsante "Annulla selezione").
294	     */
295	    public function clearAssetSelection(): void
296	    {
297	        $this->selectedAssetIds = [];
298	    }
299	
300	    /**
301	     * Seleziona tutti gli asset attualmente visibili nella vista corrente
302	     * (pulsante "Seleziona tutti", disponibile dopo la prima selezione).
303	     */
304	    public function selectAllAssets(): void
305	    {
306	        $this->selectedAssetIds = $this->getAssets()
307	            ->map(function (Media $media): string {
308	                $key = $media->getKey();
309	
310	                return is_int($key) || is_string($key) ? (string) $key : '';
311	            })
312	            ->all();
313	    }
314	
315	    /**
316	     * Sposta un media in una folder (o root) via drag-drop sull'albero (#16b).
317	     * `$mediaId` arriva come stringa dal dataTransfer; `$folderId` null = root.
318	     */
319	    public function moveAssetToFolder(mixed $mediaId, ?int $folderId): void
320	    {
321	        $media = $this->findOwnedMedia($mediaId);
322	        if ($media === null) {
323	            return;
324	        }
325	
326	        if ($folderId !== null && $this->findOwnedFolder($folderId) === null) {
327	            $folderId = null;
328	        }
329	
330	        $media->setAttribute('asset_folder_id', $folderId);
331	        $media->save();
332	
333	        Notification::make()->success()->title(__('digital-hub::assets.asset_moved'))->send();
334	    }
335	
336	    /**
337	     * Riordina un gruppo di folder fratelli via drag-drop nell'albero (#16b).
338	     * Riceve gli id nel nuovo ordine (da SortableJS) e riassegna `sort` per
339	     * posizione. Gli id estranei al record sono ignorati.
340	     *
341	     * @param array<int, int|string> $orderedIds
342	     */
343	    public function reorderFolders(array $orderedIds): void
344	    {
345	        foreach (array_values($orderedIds) as $index => $id) {
346	            $folder = $this->findOwnedFolder($id);
347	            if ($folder === null) {
348	                continue;
349	            }
350	
351	            if ($folder->sort !== $index) {
352	                $folder->sort = $index;
353	                $folder->save();
354	            }
355	        }
356	
357	        $this->folderCache = null;
358	    }
359	
360	    /**
361	     * Albero annidato delle folder del record per il pannello sinistro.
362	     * `children` è ricorsivamente la stessa struttura (non esprimibile come tipo
363	     * ricorsivo preciso in PHPDoc, quindi `mixed`).
364	     *
365	     * @return array<int, array{folder: AssetFolder, children: mixed}>
366	     */
367	    public function getFolderTree(): array
368	    {
369	        return $this->buildTree(null);
370	    }
371	
372	    /**
373	     * @return array<int, array{folder: AssetFolder, children: mixed}>
374	     */
375	    private function buildTree(?int $parentId): array
376	    {
377	        return $this->allFolders()
378	            ->where('parent_id', $parentId)
379	            ->map(fn (AssetFolder $folder): array => [
380	                'folder' => $folder,
381	                'children' => $this->buildTree($folder->id),
382	            ])
383	            ->values()
384	            ->all();
385	    }
386	
387	    /**
388	     * Sottocartelle dirette della folder attiva, da mostrare come tile nel
389	     * pannello destro insieme ai file. Vuota in "Tutti gli asset" (root): lì la
390	     * vista resta l'aggregato piatto di soli file.
391	     *
392	     * @return \Illuminate\Support\Collection<int, AssetFolder>
393	     */
394	    public function getSubfolders(): \Illuminate\Support\Collection
395	    {
396	        if ($this->activeFolderId === null) {
397	            return new \Illuminate\Support\Collection();
398	        }
399	
400	        return $this->allFolders()
401	            ->where('parent_id', $this->activeFolderId)
402	            ->values();
403	    }
404	
405	    /**
406	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
407	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
408	     *
409	     * @return list<AssetFolder>
410	     */
411	    public function getBreadcrumbTrail(): array
412	    {
413	        if ($this->activeFolderId === null) {
414	            return [];
415	        }
416	
417	        $folders = $this->allFolders();
418	        $trail = [];
419	        $id = $this->activeFolderId;
420	
421	        while ($id !== null) {
422	            $folder = $folders->firstWhere('id', $id);
423	            if (! $folder instanceof AssetFolder) {
424	                // folder eliminata sotto i piedi: torna a root
425	                $this->activeFolderId = null;
426	
427	                return [];
428	            }
429	
430	            array_unshift($trail, $folder);
431	            $id = $folder->parent_id;
432	        }
433	
434	        return $trail;
435	    }
436	
437	    /**
438	     * Media mostrati nel pannello destro. Sulla voce "Tutti gli asset"
439	     * (nessuna folder attiva) è la vista aggregata di TUTTI i media del record;
440	     * su una folder, i soli media diretti di quella folder.
441	     *
442	     * @return \Illuminate\Support\Collection<int, \Spatie\MediaLibrary\MediaCollections\Models\Media>
443	     */
444	    public function getAssets(): \Illuminate\Support\Collection
445	    {
446	        $owner = $this->resolveOwner();
447	
448	        if ($this->activeFolderId === null) {
449	            return $owner->allAssets();
450	        }
451	
452	        return $owner->assetsInFolder($this->findOwnedFolder($this->activeFolderId));
453	    }
454	
455	    /**
456	     * Percorso completo (root → cartella) del media, per il badge nella vista
457	     * aggregata "Tutti gli asset". Es. "Documenti / 2024".
458	     * null = media non assegnato a nessuna folder.
459	     */
460	    public function assetFolderPath(Media $media): ?string
461	    {
462	        $id = $media->getAttribute('asset_folder_id');
463	        if (! is_numeric($id)) {
464	            return null;
465	        }
466	
467	        $folders = $this->allFolders();
468	        $names = [];
469	        $current = (int) $id;
470	        $guard = 0;
471	
472	        while ($current !== null) {
473	            $folder = $folders->firstWhere('id', $current);
474	            if (! $folder instanceof AssetFolder) {
475	                break;
476	            }
477	
478	            array_unshift($names, $folder->name);
479	            $current = $folder->parent_id;
480	
481	            if (++$guard > AssetFolder::MAX_DEPTH + 1) {
482	                break; // safety contro catene anomale
483	            }
484	        }
485	
486	        return $names === [] ? null : implode(' / ', $names);
487	    }
488	
489	    // -- Preview delle cartelle (14b) -----------------------------------------
490	
491	    /** Numero massimo di miniature nel collage della tile cartella. */
492	    public const FOLDER_PREVIEW_LIMIT = 4;
493	
494	    /**
495	     * Miniature per le tile delle sottocartelle: per ogni sottocartella diretta
496	     * della folder attiva, fino a FOLDER_PREVIEW_LIMIT URL di anteprima presi
497	     * dai media contenuti nella cartella o nei suoi discendenti (ordine
498	     * order_column, come la griglia). "Mostrabile" = ha il poster generato dal
499	     * job, oppure è un'immagine (l'originale è già leggero). I media ancora in
500	     * lavorazione o senza anteprima vengono saltati: la tile ricade sull'icona
501	     * finché non c'è nulla di mostrabile.
502	     *
503	     * Derivata pura, niente da persistere: se il contenuto della cartella cambia
504	     * (spostamenti, delete, job completati) il prossimo render riflette lo stato.
505	     *
506	     * @return array<int, list<string>> id sottocartella => URL miniature
507	     */
508	    public function getSubfolderPreviews(): array
509	    {
510	        $tileMap = $this->tileBySubtreeFolder();
511	
512	        $previews = [];
513	        foreach ($this->getSubfolders() as $subfolder) {
514	            $previews[$subfolder->id] = [];
515	        }
516	
517	        foreach ($this->subfolderMedia() as $media) {
518	            $tileId = $this->tileForMedia($media, $tileMap);
519	            if ($tileId === null || count($previews[$tileId]) >= self::FOLDER_PREVIEW_LIMIT) {
520	                continue;
521	            }
522	
523	            // stessa catena di fallback della card asset: poster → originale se immagine
524	            $url = AssetPreview::url($media)
525	                ?? (AssetFileType::fromMedia($media)->isImage() ? AssetUrl::original($media) : null);
526	
527	            if ($url !== null) {
528	                $previews[$tileId][] = $url;
529	            }
530	        }
531	
532	        return $previews;
533	    }
534	
535	    /**
536	     * Numero totale di file per ogni sottocartella visibile, discendenti
537	     * compresi, mostrato sotto il nome della tile. Conta sulla collezione già
538	     * caricata per le preview ({@see self::subfolderMedia()}): nessuna query
539	     * aggiuntiva.
540	     *
541	     * @return array<int, int> id sottocartella => numero di file nel sottoalbero
542	     */
543	    public function getSubfolderFileCounts(): array
544	    {
545	        $tileMap = $this->tileBySubtreeFolder();
546	
547	        $counts = [];
548	        foreach ($this->getSubfolders() as $subfolder) {
549	            $counts[$subfolder->id] = 0;
550	        }
551	
552	        foreach ($this->subfolderMedia() as $media) {
553	            $tileId = $this->tileForMedia($media, $tileMap);
554	            if ($tileId !== null) {
555	                $counts[$tileId]++;
556	            }
557	        }
558	
559	        return $counts;
560	    }
561	
562	    /**
563	     * Mappa ogni folder dei sottoalberi visibili (sottocartella diretta della
564	     * folder attiva o sua discendente) all'id della sottocartella-tile che la
565	     * contiene. Camminata sull'albero già in memoria.
566	     *
567	     * @return array<int, int>
568	     */
569	    private function tileBySubtreeFolder(): array
570	    {
571	        $map = [];
572	
573	        foreach ($this->getSubfolders() as $subfolder) {
574	            foreach ($this->descendantFolderIds($subfolder) as $id) {
575	                $map[$id] = $subfolder->id;
576	            }
577	        }
578	
579	        return $map;
580	    }
581	
582	    /**
583	     * Id della sottocartella-tile a cui il media afferisce (direttamente o via
584	     * discendenti), o null se fuori dai sottoalberi visibili.
585	     *
586	     * @param array<int, int> $tileMap da {@see self::tileBySubtreeFolder()}
587	     */
588	    private function tileForMedia(Media $media, array $tileMap): ?int
589	    {
590	        $folderId = $media->getAttribute('asset_folder_id');
591	
592	        return is_numeric($folderId) ? ($tileMap[(int) $folderId] ?? null) : null;
593	    }
594	
595	    /**
596	     * True se tra i media dei sottoalberi delle sottocartelle visibili ce n'è
597	     * almeno uno in lavorazione: estende il polling della griglia (che guarda
598	     * solo gli asset della folder attiva) così le preview delle tile cartella
599	     * compaiono da sole a job concluso.
600	     */
601	    public function hasProcessingInSubfolders(): bool
602	    {
603	        return $this->subfolderMedia()->contains(
604	            fn (Media $media): bool => $this->assetStatus($media)?->isInProgress() ?? false,
605	        );
606	    }
607	
608	    /**
609	     * Id della folder e di tutte le sue discendenti, camminando l'albero già
610	     * cachato in memoria ({@see self::allFolders()}): nessuna query aggiuntiva.
611	     *
612	     * @return list<int>
613	     */
614	    private function descendantFolderIds(AssetFolder $folder): array
615	    {
616	        $ids = [$folder->id];
617	
