630	     */
631	    private function subfolderMedia(): \Illuminate\Support\Collection
632	    {
633	        if ($this->subfolderMediaCache !== null) {
634	            return $this->subfolderMediaCache;
635	        }
636	
637	        $ids = [];
638	        foreach ($this->getSubfolders() as $subfolder) {
639	            $ids = array_merge($ids, $this->descendantFolderIds($subfolder));
640	        }
