845	    /**
846	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
847	     * I file finiscono nella collection asset del record (disco scoped).
848	     */
849	    public function uploadAssetsAction(): Action
850	    {
851	        return Action::make('uploadAssets')
852	            ->label(__('digital-hub::assets.upload'))
853	            ->icon(Heroicon::OutlinedArrowUpTray)
854	            ->modalHeading(__('digital-hub::assets.upload_heading'))
855	            ->schema([
856	                FileUpload::make('files')
857	                    ->label(__('digital-hub::assets.files_field'))
858	                    ->multiple()
859	                    ->required()
860	                    ->storeFiles(false),
861	            ])
862	            ->action(function (array $data): void {
863	                $owner = $this->resolveOwner();
864	                $files = $data['files'] ?? [];
865	                if (! is_array($files)) {
866	                    return;
867	                }
868	
869	                $count = 0;
870	                foreach ($files as $file) {
871	                    if (! $file instanceof TemporaryUploadedFile) {
872	                        continue;
873	                    }
874	
875	                    $media = $owner->addMedia($file)
876	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
877	                        ->toMediaCollection($owner->assetsCollection());
878	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
879	
880	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
881	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
882	                    /** @disregard P1013 */
883	                    $user = auth()->user();
884	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
885	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
886	
887	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
888	                    // job in coda: il media entra "pending" finché il job non lo chiude
889	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
890	                    $media->save();
891	
892	                    $this->dispatchProcessing($media);
893	                    $count++;
894	                }
895	
896	                if ($count > 0) {
897	                    Notification::make()
898	                        ->success()
899	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
900	                        ->send();
901	                }
902	            });
903	    }
